'use client';

import { Switch as SwitchPrimitive } from '@base-ui/react/switch';

import {
  MobileNav,
  MobileNavLinks,
} from '@/registry/ndeko/components/navbar/_parts/mobile-nav';
import {
  NavLinks,
  type NavLinkItem,
} from '@/registry/ndeko/components/navbar/_parts/nav-links';
import { useActiveLink } from '@/registry/ndeko/components/navbar/_parts/use-active-link';
import {
  ClockIcon,
  PowerIcon,
  PowerOffIcon,
  ZapIcon,
} from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Badge } from '@/registry/ndeko/ui/badge';

const LINKS: NavLinkItem[] = [
  { href: '#', label: 'Overview' },
  { href: '#', label: 'Graphs' },
  { href: '#', label: 'Backups' },
];

const POWER_TRACK = [
  'group/power inline-flex h-7 w-12 shrink-0 cursor-pointer items-center rounded-full bg-foreground/15 p-0.5 outline-none',
  'transition-colors duration-200 ease-(--ease-out-strong) focus-visible:ring-[3px] focus-visible:ring-ring/25',
  'data-checked:bg-primary dark:bg-foreground/20',
].join(' ');

const POWER_THUMB = [
  'relative flex size-6 items-center justify-center rounded-full bg-white',
  'shadow-[0_1px_2px_rgb(0_0_0/0.2),0_0_0_var(--hairline)_rgb(0_0_0/0.04)]',
  'transition-[translate] duration-200 ease-(--ease-out-strong) data-checked:translate-x-5',
].join(' ');

const POWER_GLYPH =
  'absolute size-3.5 transition-[opacity,scale] duration-150 ease-(--ease-out-strong)';

export default function Navbar20() {
  const { activeLabel, navigate } = useActiveLink('Overview');

  return (
    <header className='hairline-b border-border px-4 md:px-6'>
      <div className='flex h-16 justify-between gap-4'>
        <div className='flex gap-2'>
          <div className='flex items-center md:hidden'>
            <MobileNav className='w-36'>
              <MobileNavLinks
                links={LINKS}
                activeLabel={activeLabel}
                onNavigate={navigate}
              />
            </MobileNav>
          </div>
          <NavLinks
            links={LINKS}
            activeLabel={activeLabel}
            onNavigate={navigate}
            indicator='underline'
            className='max-md:hidden'
          />
        </div>
        <div className='flex items-center gap-4'>
          <div className='flex items-center gap-2'>
            <Badge variant='success' className='gap-1.5'>
              <span
                aria-hidden='true'
                className='bg-success size-1.5 rounded-full'
              />
              Online
            </Badge>
            <Badge variant='outline' className='gap-1.5 tabular-nums'>
              <ZapIcon className='opacity-60' />
              <span className='sr-only'>Uptime</span>
              99.9%
            </Badge>
            <Badge variant='outline' className='gap-1.5 tabular-nums'>
              <ClockIcon className='opacity-60' />
              <span className='sr-only'>Response time</span>
              45ms
            </Badge>
          </div>
          <SwitchPrimitive.Root
            defaultChecked
            aria-label='Server power'
            className={POWER_TRACK}
          >
            <SwitchPrimitive.Thumb className={POWER_THUMB}>
              <PowerOffIcon
                className={cn(
                  POWER_GLYPH,
                  'text-muted-foreground group-data-checked/power:scale-75 group-data-checked/power:opacity-0'
                )}
              />
              <PowerIcon
                className={cn(
                  POWER_GLYPH,
                  'text-primary-ink scale-75 opacity-0 group-data-checked/power:scale-100 group-data-checked/power:opacity-100'
                )}
              />
            </SwitchPrimitive.Thumb>
          </SwitchPrimitive.Root>
        </div>
      </div>
    </header>
  );
}

'use client';

import { createContext, useContext, useState } from 'react';

import {
  isPlaceholderHref,
  NavLinkIcon,
  type NavLinkItem,
} from '@/registry/ndeko/components/navbar/_parts/nav-links';
import {
  MENU_ITEM,
  MENU_LABEL,
  MENU_SEPARATOR,
} from '@/registry/ndeko/lib/recipes';
import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '@/registry/ndeko/ui/popover';

const CloseMenuContext = createContext<() => void>(() => undefined);

const BAR =
  'origin-center transition-[translate,rotate] duration-300 ease-(--ease-out-strong)';

const LINK_ROW = cn(
  MENU_ITEM,
  'text-muted-foreground cursor-pointer transition-colors duration-150',
  'hover:bg-foreground/5 hover:text-foreground focus-visible:bg-foreground/5 focus-visible:text-foreground',
  'data-active:bg-foreground/[0.06] data-active:text-foreground dark:data-active:bg-foreground/10'
);

function menuLabelOf(isOpen: boolean) {
  if (isOpen) {
    return 'Close menu';
  }
  return 'Open menu';
}

function ariaCurrentOf(isActive: boolean) {
  if (isActive) {
    return 'page' as const;
  }
  return undefined;
}

function MenuToggleIcon() {
  return (
    <svg
      viewBox='0 0 24 24'
      fill='none'
      stroke='currentColor'
      strokeWidth='1.75'
      strokeLinecap='round'
      strokeLinejoin='round'
      aria-hidden='true'
      className='pointer-events-none size-4'
    >
      <path
        d='M4 12H20'
        className={cn(
          BAR,
          '-translate-y-[7px] group-aria-expanded/button:translate-y-0 group-aria-expanded/button:rotate-[315deg]'
        )}
      />
      <path
        d='M4 12H20'
        className={cn(BAR, 'group-aria-expanded/button:rotate-45')}
      />
      <path
        d='M4 12H20'
        className={cn(
          BAR,
          'translate-y-[7px] group-aria-expanded/button:translate-y-0 group-aria-expanded/button:rotate-[135deg]'
        )}
      />
    </svg>
  );
}

type MobileNavProps = {
  children: React.ReactNode;
  className?: string;
};

function MobileNav({ children, className }: MobileNavProps) {
  const [isOpen, setIsOpen] = useState(false);

  function changeOpen(open: boolean) {
    setIsOpen(open);
  }

  function closeMenu() {
    setIsOpen(false);
  }

  return (
    <Popover open={isOpen} onOpenChange={changeOpen}>
      <PopoverTrigger
        render={
          <Button
            variant='ghost'
            size='icon'
            aria-label={menuLabelOf(isOpen)}
            className='md:hidden'
          />
        }
      >
        <MenuToggleIcon />
      </PopoverTrigger>
      <PopoverContent
        align='start'
        className={cn('w-44 p-1 md:hidden', className)}
      >
        <nav aria-label='Main'>
          <CloseMenuContext.Provider value={closeMenu}>
            {children}
          </CloseMenuContext.Provider>
        </nav>
      </PopoverContent>
    </Popover>
  );
}

type MobileNavLinkProps = {
  href: string;
  isActive?: boolean;
  onClick?: () => void;
  className?: string;
  children: React.ReactNode;
};

function MobileNavLink({
  href,
  isActive = false,
  onClick,
  className,
  children,
}: MobileNavLinkProps) {
  const closeMenu = useContext(CloseMenuContext);

  function follow(event: React.MouseEvent<HTMLAnchorElement>) {
    if (isPlaceholderHref(href)) {
      event.preventDefault();
    }
    onClick?.();
    closeMenu();
  }

  return (
    <a
      href={href}
      aria-current={ariaCurrentOf(isActive)}
      data-active={isActive || undefined}
      onClick={follow}
      className={cn(LINK_ROW, className)}
    >
      {children}
    </a>
  );
}

type MobileNavLinksProps = {
  links: NavLinkItem[];
  activeLabel?: string;
  onNavigate?: (label: string) => void;
  showsIcons?: boolean;
};

function MobileNavLinks({
  links,
  activeLabel,
  onNavigate,
  showsIcons = false,
}: MobileNavLinksProps) {
  return (
    <ul className='flex flex-col'>
      {links.map((link) => (
        <li key={link.label}>
          <MobileNavLink
            href={link.href}
            isActive={link.label === activeLabel}
            onClick={() => onNavigate?.(link.label)}
          >
            {showsIcons && <NavLinkIcon icon={link.icon} />}
            {link.label}
          </MobileNavLink>
        </li>
      ))}
    </ul>
  );
}

function MobileNavHeading({ children }: { children: React.ReactNode }) {
  return <div className={MENU_LABEL}>{children}</div>;
}

function MobileNavSeparator() {
  return (
    <div
      role='separator'
      aria-orientation='horizontal'
      className={MENU_SEPARATOR}
    />
  );
}

export {
  MobileNav,
  MobileNavHeading,
  MobileNavLink,
  MobileNavLinks,
  MobileNavSeparator,
};

'use client';

import {
  LayoutGroup,
  motion,
  type Transition,
  useReducedMotion,
} from 'motion/react';
import { useId } from 'react';

import type { Icon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import {
  NavigationMenu,
  NavigationMenuItem,
  NavigationMenuLink,
  NavigationMenuList,
} from '@/registry/ndeko/ui/navigation-menu';
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from '@/registry/ndeko/ui/tooltip';

type NavLinkItem = { label: string; href: string; icon?: Icon };

type NavIndicator = 'pill' | 'underline';

type NavLinkDisplay = 'label' | 'icon-label' | 'icon';

const SLIDE_TRANSITION: Transition = {
  type: 'spring',
  bounce: 0,
  duration: 0.3,
};
const INSTANT_TRANSITION: Transition = { duration: 0 };

const LINK_BASE =
  'relative flex-row items-center gap-2 py-0 font-medium text-muted-foreground hover:bg-transparent hover:text-foreground data-active:bg-transparent data-active:text-foreground';

const LINK_SHAPE: Record<NavIndicator, string> = {
  pill: 'h-8 rounded-md px-3',
  underline: 'h-full rounded-sm px-0.5',
};

const ICON_ONLY_SHAPE = 'size-8 justify-center px-0';

const LIST_CLASS: Record<NavIndicator, string> = {
  pill: 'gap-1',
  underline: 'h-full gap-6',
};

const ITEM_CLASS: Record<NavIndicator, string> = {
  pill: '',
  underline: 'h-full',
};

const INDICATOR_CLASS: Record<NavIndicator, string> = {
  pill: 'absolute inset-0 rounded-md bg-foreground/[0.06] dark:bg-foreground/10',
  underline: 'absolute inset-x-0 bottom-0 h-0.5 rounded-full bg-primary',
};

function slideTransitionOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return INSTANT_TRANSITION;
  }
  return SLIDE_TRANSITION;
}

function isPlaceholderHref(href: string) {
  return href === '#';
}

function NavLinkIcon({ icon: LinkIcon }: { icon?: Icon }) {
  if (!LinkIcon) {
    return null;
  }
  return <LinkIcon className='size-4' />;
}

type NavLinksItemProps = {
  link: NavLinkItem;
  isActive: boolean;
  indicator: NavIndicator;
  display: NavLinkDisplay;
  transition: Transition;
  onFollow: (
    event: React.MouseEvent<HTMLAnchorElement>,
    link: NavLinkItem
  ) => void;
};

function NavLinksItem({
  link,
  isActive,
  indicator,
  display,
  transition,
  onFollow,
}: NavLinksItemProps) {
  const isIconOnly = display === 'icon';
  const showsIcon = display !== 'label';
  const linkClassName = cn(
    LINK_BASE,
    LINK_SHAPE[indicator],
    isIconOnly && ICON_ONLY_SHAPE
  );

  function follow(event: React.MouseEvent<HTMLAnchorElement>) {
    onFollow(event, link);
  }

  const content = (
    <>
      {isActive && (
        <motion.span
          layoutId='active-link-indicator'
          transition={transition}
          className={INDICATOR_CLASS[indicator]}
        />
      )}
      <span className='relative flex items-center gap-2'>
        {showsIcon && <NavLinkIcon icon={link.icon} />}
        {isIconOnly && <span className='sr-only'>{link.label}</span>}
        {!isIconOnly && link.label}
      </span>
    </>
  );

  if (isIconOnly) {
    return (
      <NavigationMenuItem className={ITEM_CLASS[indicator]}>
        <Tooltip>
          <TooltipTrigger
            render={
              <NavigationMenuLink
                href={link.href}
                active={isActive}
                onClick={follow}
                className={linkClassName}
              />
            }
          >
            {content}
          </TooltipTrigger>
          <TooltipContent side='bottom'>{link.label}</TooltipContent>
        </Tooltip>
      </NavigationMenuItem>
    );
  }

  return (
    <NavigationMenuItem className={ITEM_CLASS[indicator]}>
      <NavigationMenuLink
        href={link.href}
        active={isActive}
        onClick={follow}
        className={linkClassName}
      >
        {content}
      </NavigationMenuLink>
    </NavigationMenuItem>
  );
}

type NavLinksProps = {
  links: NavLinkItem[];
  activeLabel?: string;
  onNavigate: (label: string) => void;
  indicator?: NavIndicator;
  display?: NavLinkDisplay;
  className?: string;
};

function NavLinks({
  links,
  activeLabel,
  onNavigate,
  indicator = 'pill',
  display = 'label',
  className,
}: NavLinksProps) {
  const groupId = useId();
  const shouldReduceMotion = useReducedMotion();
  const transition = slideTransitionOf(shouldReduceMotion);
  const isUnderline = indicator === 'underline';

  function followLink(
    event: React.MouseEvent<HTMLAnchorElement>,
    link: NavLinkItem
  ) {
    if (isPlaceholderHref(link.href)) {
      event.preventDefault();
    }
    onNavigate(link.label);
  }

  return (
    <LayoutGroup id={groupId}>
      <TooltipProvider>
        <NavigationMenu
          aria-label='Main'
          className={cn(isUnderline && 'h-full', className)}
        >
          <NavigationMenuList className={LIST_CLASS[indicator]}>
            {links.map((link) => (
              <NavLinksItem
                key={link.label}
                link={link}
                isActive={link.label === activeLabel}
                indicator={indicator}
                display={display}
                transition={transition}
                onFollow={followLink}
              />
            ))}
          </NavigationMenuList>
        </NavigationMenu>
      </TooltipProvider>
    </LayoutGroup>
  );
}

export {
  NavLinkIcon,
  NavLinks,
  isPlaceholderHref,
  type NavIndicator,
  type NavLinkDisplay,
  type NavLinkItem,
};

import { useState } from 'react';

function useActiveLink(initialLabel?: string) {
  const [activeLabel, setActiveLabel] = useState(initialLabel);

  function navigate(label: string) {
    setActiveLabel(label);
  }

  return { activeLabel, navigate };
}

export { useActiveLink };
